<?php
declare(strict_types=1);require_once __DIR__.'/includes/admin_auth.php';require_once __DIR__.'/includes/csrf.php';require_once __DIR__.'/connection.php';mysqli_query($connection,'CREATE TABLE IF NOT EXISTS system_settings(id INT AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) UNIQUE,setting_value TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)');$defaults=['site_name'=>'AlumTrace','support_email'=>'support@alumtrace.edu','contact_phone'=>'+63 9161 196 5036'];foreach($defaults as $k=>$v){$s=mysqli_prepare($connection,'INSERT IGNORE INTO system_settings(setting_key,setting_value) VALUES(?,?)');mysqli_stmt_bind_param($s,'ss',$k,$v);mysqli_stmt_execute($s);mysqli_stmt_close($s);}$settings=$defaults;$r=mysqli_query($connection,'SELECT setting_key,setting_value FROM system_settings');if($r)while($row=mysqli_fetch_assoc($r))$settings[$row['setting_key']]=$row['setting_value'];$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($defaults as $k=>$v){$value=trim($_POST[$k]??$v);$s=mysqli_prepare($connection,'INSERT INTO system_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');mysqli_stmt_bind_param($s,'ss',$k,$value);mysqli_stmt_execute($s);mysqli_stmt_close($s);}$message='Settings saved successfully.';}$pageTitle='Admin Settings';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><div class="page-head"><h2>System Settings</h2><p>Manage the identity and support contact information shown across AlumTrace.</p></div><?php if($message):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><?php endif;?><div class="panel settings-panel"><form method="post"><?=csrf_field()?><div class="field"><label>Site name</label><input class="input" name="site_name" value="<?=htmlspecialchars($settings['site_name'])?>"></div><div class="field"><label>Support email</label><input class="input" type="email" name="support_email" value="<?=htmlspecialchars($settings['support_email'])?>"></div><div class="field"><label>Contact phone</label><input class="input" name="contact_phone" value="<?=htmlspecialchars($settings['contact_phone'])?>"></div><button class="btn btn-primary" type="submit">Save settings</button></form></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
